class Label:
    def __init__(self, text):
        self.text = text
    def upper(self):
        return self.text.upper()
label = Label("ready")
print(label.upper())

class Flag:
    def __init__(self, enabled):
        if enabled:
            self.message = "ready"
flag = Flag(True)
print(flag.message)

